// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager, IERC20, IGlpManager, IRewardRouterV2} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    MockToken token;
    MockJuniorVault junior;
    MockRouter router;
    MockGlpManager mgr;

    function setUp() public {
        c = new DnGmxBatchingManager();
        token = new MockToken();
        junior = new MockJuniorVault();
        router = new MockRouter();
        mgr = new MockGlpManager();
        junior.setC(c);
        c.initialize(IERC20(address(token)), IERC20(address(token)), IRewardRouterV2(address(router)), IGlpManager(address(mgr)), address(junior), address(this));
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);

        // accumulate GLP balance on c's behalf via depositToken from the junior vault
        vm.prank(address(junior));
        c.depositToken(address(token), amount, 0);
        assertEq(c.dnGmxJuniorVaultGlpBalance(), amount); // setup sanity, not the property

        // first batch deposit after cooldown
        vm.warp(3600);
        c.executeBatchDeposit();
        // second batch deposit after a fresh cooldown
        vm.warp(3600 + 1800);
        c.executeBatchDeposit();

        // RULE: across the two flushes the junior vault received the staked amount EXACTLY ONCE.
        assertTrue(token.totalSentTo(address(junior)) == amount);
    }
}

contract MockToken {
    mapping(address => uint256) public totalSentTo;
    function transferFrom(address, address, uint256) external returns (bool) { return true; }
    function approve(address, uint256) external returns (bool) { return true; }
    function transfer(address to, uint256 amt) external returns (bool) { totalSentTo[to] += amt; return true; }
    function balanceOf(address) external view returns (uint256) { return 0; }
}

contract MockJuniorVault {
    DnGmxBatchingManager public c;
    function setC(DnGmxBatchingManager _c) external { c = _c; }
    function depositToken(address token, uint256 amount, uint256 minUSDG) external {
        c.depositToken(token, amount, minUSDG);
    }
    function harvestFees() external {}
    function deposit(uint256, address) external returns (uint256) { return 0; }
    function transfer(address, uint256) external returns (bool) { return true; }
    function balanceOf(address) external view returns (uint256) { return 0; }
    function redeem(uint256, address, address) external returns (uint256) { return 0; }
}

contract MockRouter {
    function mintAndStakeGlp(address, uint256 amount, uint256, uint256) external returns (uint256) { return amount; }
}

contract MockGlpManager {
    function vault() external view returns (address) { return address(this); }
    function getMinPrice(address) external view returns (uint256) { return 1; }
}
